actor ControlledInboxLinkLeadPort:SyntheticInboxLinkLeadPort {
    nonisolated let grants:[SyntheticInboxLinkLeadGrant]
    private var attempts:[InboxLinkLeadAttempt]=[]
    private var pending:[Int:CheckedContinuation<SyntheticInboxLinkLeadOutcome,any Error>]=[:],waiters:[Int:CheckedContinuation<Void,Never>]=[:]
    init(_ grants:[SyntheticInboxLinkLeadGrant]) {self.grants=grants}
    func execute(_ a:InboxLinkLeadAttempt) async throws -> SyntheticInboxLinkLeadOutcome {let i=attempts.count;attempts.append(a);return try await withCheckedThrowingContinuation {pending[i]=$0;waiters.removeValue(forKey:i)?.resume()}}
    func wait(_ i:Int) async {if pending[i]==nil {await withCheckedContinuation {waiters[i]=$0}}}
    func resolve(_ i:Int,_ value:SyntheticInboxLinkLeadOutcome) {pending.removeValue(forKey:i)!.resume(returning:value)}
    func fail(_ i:Int) {pending.removeValue(forKey:i)!.resume(throwing:ReadFailure.unavailable)}
    func recorded()->[InboxLinkLeadAttempt] {attempts}
}
